/* Public, curated from the UNFCCC AUVs and IISD Earth Negotiations Bulletin. */
window.COP31_RESULTS_DATA=(()=>{
  const enb='https://enb.iisd.org/antalya-un-climate-change-conference-cop31-summary';
  const u=id=>'https://unfccc.int/documents/'+id;
  // Copy fields: title, what happened, why it matters. The ruling is not a publication status.
  return {
    outcomes:[
      {id:'antalya-pact',topic:'package',body:'COP 31 · 2(f)',status:'notAdopted',stage:'draft',source:enb,
       en:['Antalya Pact: Convention cover text','The proposed COP cover decision did not secure consensus, nor did its companion Paris Agreement text.','Draft FCCC/CP/2026/L.14 included proposals on mountains, climate funds and the UN climate process. They were not adopted through this cover text; decisions on separate items stand on their own.'],
       pt:['Pacto de Antália: texto de capa da Convenção','O texto de capa proposto para a COP não obteve consenso, nem seu equivalente no Acordo de Paris.','O projeto FCCC/CP/2026/L.14 trazia propostas sobre montanhas, fundos climáticos e o processo da ONU sobre clima. Elas não foram aprovadas por meio desse texto de capa; decisões sobre outros itens têm tramitação própria.']},
      {id:'antalya-pact-cma',topic:'package',body:'CMA 8 · 2(c)',status:'notAdopted',stage:'draft',source:enb,
       en:['Antalya Pact: Paris Agreement cover text','The proposed Paris Agreement cover decision did not secure consensus.','Draft FCCC/PA/CMA/2026/L.25 included proposals on electrification and carbon capture, use and storage. It did not create new commitments or change the outcomes already agreed in Dubai or Belém.'],
       pt:['Pacto de Antália: texto de capa do Acordo de Paris','O texto de capa proposto para o Acordo de Paris não obteve consenso.','O projeto FCCC/PA/CMA/2026/L.25 trazia propostas sobre eletrificação e captura, uso e armazenamento de carbono. Não criou novos compromissos nem alterou os resultados já aprovados em Dubai ou Belém.']},
      {id:'adaptation',topic:'adaptation',body:'CMA 8 · 9(a)',status:'adopted',stage:'auv',source:u(665895),
       en:['Global goal on adaptation','Parties agreed on voluntary testing of the adaptation indicators and work to improve their methods.','Testing will show how useful the indicators are for tracking adaptation progress. The decision does not itself provide funding.'],
       pt:['Meta global de adaptação','As Partes concordaram em testar voluntariamente os indicadores de adaptação e aprimorar suas metodologias.','Os testes ajudarão a avaliar se os indicadores servem para acompanhar o progresso em adaptação. A decisão, por si só, não destina recursos.']},
      {id:'just-transition',topic:'justice',body:'CMA 8 · 5',status:'adopted',stage:'auv',source:u(665900),
       en:['Just transition work programme','Parties extended the programme for three years and agreed to put the just transition mechanism into operation in phases.','The programme continues while Parties work out how the mechanism will function.'],
       pt:['Programa de trabalho sobre transição justa','As Partes prorrogaram o programa por três anos e decidiram operacionalizar o mecanismo de transição justa em etapas.','O programa segue enquanto as Partes definem como o mecanismo funcionará.']},
      {id:'climate-finance',topic:'finance',body:'CMA 8 · 11(g)',status:'adopted',stage:'auv',source:u(665903),
       en:['Climate finance work programme','Parties agreed how to run the programme on climate finance under Article 9, including workshops, submissions and reports.','The decision sets a process for discussing delivery of climate finance; it does not itself commit new money.'],
       pt:['Programa de trabalho sobre financiamento climático','As Partes definiram como funcionará o programa sobre financiamento climático no âmbito do Artigo 9, com oficinas, contribuições escritas e relatórios.','A decisão estabelece um processo para discutir a entrega de financiamento climático, mas não compromete novos recursos.']},
      {id:'finance-flows',topic:'finance',body:'CMA 8 · 11(f)',status:'adopted',stage:'auv',source:u(665898),
       en:['Alignment of financial flows','Parties adopted a decision on Article 2.1(c) and its relationship to Article 9.','Aligning financial flows with climate goals and providing climate finance are distinct parts of the Paris Agreement. The adopted text addresses how they complement each other.'],
       pt:['Alinhamento dos fluxos financeiros','As Partes adotaram uma decisão sobre o Artigo 2.1(c) e sua relação com o Artigo 9.','Alinhar os fluxos financeiros às metas climáticas e prover financiamento climático são frentes distintas do Acordo de Paris. O texto adotado trata de como elas se complementam.']},
      {id:'mitigation',topic:'mitigation',body:'CMA 8 · 6',status:'notAdopted',stage:'draft',source:enb,
       en:['Mitigation work programme','Parties did not agree to the draft; the item goes to CMA 9 under the draft rules of procedure.','Carrying the agenda item forward did not extend the existing work programme.'],
       pt:['Programa de trabalho sobre mitigação','As Partes não chegaram a acordo sobre o texto. O item volta à CMA 9 pelas regras de procedimento em aplicação.','O adiamento do item não prorrogou o programa de trabalho vigente.']},
      {id:'gcf-cop',topic:'finance',body:'COP 31 · 8(c)',status:'adopted',stage:'auv',source:u(665896),
       en:['Green Climate Fund guidance (COP)','The COP adopted guidance emphasizing grant-based and highly concessional adaptation finance and encouraging stronger direct access. It noted concern over reduced developed-country commitments and pledges since the start of 2025.','The decision guides the Board and asks it to report how it implements the guidance. It does not approve a replenishment amount or a project.'],
       pt:['Orientações ao Fundo Verde para o Clima (COP)','A COP aprovou orientações que destacam doações e financiamento em condições altamente concessionais para adaptação e incentivam o acesso direto. Manifestou preocupação com a redução dos compromissos e promessas de países desenvolvidos desde o início de 2025.','A decisão orienta o Conselho e pede que relate sua implementação. Não aprova um valor de reposição de recursos nem um projeto.']},
      {id:'gcf-cma',topic:'finance',body:'CMA 8 · 11(b)',status:'adopted',stage:'auv',source:u(665901),
       en:['Green Climate Fund guidance (CMA)','The CMA asked the Board to take relevant previous climate-finance decisions into account and invited it to consider supporting the Belém Technology Implementation Programme within its mandate.','The invitation creates no separate funding window or award.'],
       pt:['Orientações ao Fundo Verde para o Clima (CMA)','A CMA pediu ao Conselho que leve em conta decisões anteriores de financiamento climático e o convidou a considerar apoio ao Programa de Implementação Tecnológica de Belém, dentro do seu mandato.','O convite não cria uma linha específica de financiamento nem concede recursos.']},
      {id:'gef-cop',topic:'finance',body:'COP 31 · 8(d)',status:'notAdopted',stage:'draft',source:enb,
       en:['Global Environment Facility guidance (COP)','The draft COP guidance did not secure consensus.','Draft FCCC/CP/2026/L.11 was not adopted. Consideration continues under decision 4/CP.29, which provides for biennial GEF guidance after 2026.'],
       pt:['Orientações ao Fundo Global para o Meio Ambiente (COP)','A proposta de orientações da COP não obteve consenso.','O projeto FCCC/CP/2026/L.11 não foi adotado. O tema segue conforme a decisão 4/CP.29, que prevê orientações bienais ao GEF após 2026.']},
      {id:'gef-cma',topic:'finance',body:'CMA 8 · 11(c)',status:'notAdopted',stage:'draft',source:enb,
       en:['Global Environment Facility guidance (CMA)','The draft Paris Agreement guidance to the GEF was not adopted.','Draft FCCC/PA/CMA/2026/L.20 did not become a decision. Consideration continues under the guidance cycle noted in decision 4/CP.29.'],
       pt:['Orientações ao Fundo Global para o Meio Ambiente (CMA)','A proposta de orientações ao GEF no âmbito do Acordo de Paris não foi adotada.','O projeto FCCC/PA/CMA/2026/L.20 não se tornou uma decisão. O tema segue no ciclo de orientações previsto na decisão 4/CP.29.']},
      {id:'loss-and-damage-fund',topic:'loss',body:'COP 31 · 8(e)',status:'adopted',stage:'auv',source:u(665889),
       en:['Fund for responding to loss and damage','The COP adopted guidance to the Fund and considered the Fund’s report.','This is guidance to the Fund, not a record of contributions pledged or paid.'],
       pt:['Fundo de resposta a perdas e danos','A COP adotou orientações ao Fundo e examinou seu relatório.','A decisão orienta o Fundo; não é um registro de contribuições prometidas ou pagas.']},
      {id:'loss-and-damage-fund-cma',topic:'loss',body:'CMA 8 · 11(d)',status:'adopted',stage:'auv',source:u(665892),
       en:['Fund for responding to loss and damage (CMA)','The CMA adopted guidance encouraging the Board to apply lessons from the initial funding arrangements when designing the Fund’s long-term model.','Parties may submit views on future guidance. The Standing Committee on Finance is to consider them when preparing draft guidance for CMA 9.'],
       pt:['Fundo de resposta a perdas e danos (CMA)','A CMA aprovou orientações que incentivam o Conselho a aplicar as lições dos instrumentos iniciais de financiamento no desenho do modelo de longo prazo do Fundo.','As Partes podem enviar contribuições sobre as próximas orientações. O Comitê Permanente de Financiamento deve considerá-las ao preparar a proposta para a CMA 9.']},
      {id:'adaptation-fund-cmp',topic:'finance',body:'CMP 21 · 6',status:'adopted',stage:'auv',source:u(665890),
       en:['Adaptation Fund: transition trigger (CMP)','The CMP agreed that the Fund will exclusively serve the Paris Agreement when its trustee confirms in writing that it has monetized the first Article 6.4 share of proceeds and the money is available to the Fund.','The amendments taking effect on 1 January 2027 are not themselves the transition. The date of the first qualifying transfer is not set by the decision.'],
       pt:['Fundo de Adaptação: condição para a transição (CMP)','A CMP decidiu que o Fundo passará a atender exclusivamente ao Acordo de Paris quando o agente fiduciário confirmar por escrito que monetizou a primeira parcela dos recursos do Artigo 6.4 e que os valores estão disponíveis ao Fundo.','As alterações que entram em vigor em 1º de janeiro de 2027 não equivalem à transição. A decisão não fixa a data da primeira transferência que cumpra essa condição.']},
      {id:'adaptation-fund-cma',topic:'finance',body:'CMA 8 · 11(e)',status:'adopted',stage:'auv',source:u(665893),
       en:['Adaptation Fund: governance after transition (CMA)','The CMA agreed that a 17-member Board composition takes effect when the Fund exclusively serves the Paris Agreement. It requested new trustee-service terms.','The SBI is to start the fifth review at its first session after the transition. No date for that trigger is set here.'],
       pt:['Fundo de Adaptação: governança após a transição (CMA)','A CMA decidiu que a composição de 17 membros do Conselho entra em vigor quando o Fundo passar a atender exclusivamente ao Acordo de Paris. Pediu novos termos para o serviço fiduciário.','O SBI deve iniciar a quinta revisão em sua primeira sessão após a transição. A decisão não fixa a data desse marco.']},
      {id:'adaptation-fund-board-cmp',topic:'finance',body:'CMP 21 · 6',status:'adopted',stage:'auv',source:u(665891),
       en:['Adaptation Fund Board report (CMP)','The CMP took note of the Board’s report and asked it to complete transition preparations as a priority.','This is separate from the decision that sets the transition trigger. The CMP invited reporting on approvals and resource mobilization until the transition.'],
       pt:['Relatório do Conselho do Fundo de Adaptação (CMP)','A CMP tomou nota do relatório do Conselho e pediu que ele conclua, como prioridade, os preparativos da transição.','É uma decisão distinta da que fixa a condição para a transição. A CMP convidou o Conselho a relatar aprovações e mobilização de recursos até a transição.']},
      {id:'adaptation-fund-board-cma',topic:'finance',body:'CMA 8 · 11(e)',status:'adopted',stage:'auv',source:u(665902),
       en:['Adaptation Fund Board report (CMA)','The CMA took note of the Board’s report and invited it to consider better support for underserved countries.','The CMA invited the Board to report approvals by implementing-entity type and progress with resource mobilization until the transition. The decision does not itself award project finance.'],
       pt:['Relatório do Conselho do Fundo de Adaptação (CMA)','A CMA tomou nota do relatório do Conselho e o convidou a considerar formas de ampliar o apoio a países pouco atendidos.','A CMA convidou o Conselho a relatar aprovações por tipo de entidade implementadora e avanços na mobilização de recursos até a transição. A decisão não aprova financiamento de projetos.']},
      {id:'article-6-2',topic:'mitigation',body:'CMA 8 · 16(a)',status:'adopted',stage:'auv',source:u(665848),
       en:['Article 6.2: cooperative approaches','The CMA advanced implementation, including technical reviews and the accounting and reporting infrastructure for cooperative approaches.','The Secretariat is to prioritize the reporting platform and Article 6 database and hold a further dialogue on technical review results at SB 66.'],
       pt:['Artigo 6.2: abordagens cooperativas','A CMA avançou na implementação, inclusive nas revisões técnicas e na infraestrutura de contabilidade e prestação de informações para abordagens cooperativas.','O Secretariado deve priorizar a plataforma de relato e a base de dados do Artigo 6, além de realizar novo diálogo sobre resultados das revisões técnicas na SB 66.']},
      {id:'article-6-2-funding',topic:'mitigation',body:'CMA 8 · 18',status:'adopted',stage:'auv',source:u(665849),
       en:['Article 6.2: funding arrangements','The CMA adopted a decision to continue work on funding the infrastructure, expert reviews and capacity-building. It did not select a funding model or impose fees.','The Secretariat is to prepare a technical paper before SB 66. SBI 66 is to continue work with a view to recommending a decision to CMA 9.'],
       pt:['Artigo 6.2: modalidades de financiamento','A CMA aprovou uma decisão para dar continuidade ao trabalho sobre o financiamento da infraestrutura, das revisões técnicas e da capacitação. Não escolheu um modelo de financiamento nem instituiu taxas.','O Secretariado deve produzir um documento técnico antes da SB 66. O SBI 66 deve prosseguir com o trabalho, com vistas a recomendar uma decisão à CMA 9.']},
      {id:'article-6-4',topic:'mitigation',body:'CMA 8 · 16(b)',status:'adopted',stage:'auv',source:u(665844),
       en:['Paris Agreement Article 6.4','Parties adopted further guidance for the UN crediting mechanism.','The guidance applies to the mechanism as a whole; it does not approve any individual project.'],
       pt:['Artigo 6.4 do Acordo de Paris','As Partes adotaram novas orientações para o mecanismo de créditos da ONU.','As orientações se aplicam ao mecanismo e não aprovam projetos individuais.']},
      {id:'article-6-8',topic:'mitigation',body:'CMA 8 · 16(c)',status:'adopted',stage:'auv',source:u(665845),
       en:['Article 6.8: non-market approaches','The CMA agreed on workshops and invited input from Parties and observers. It sent the unresolved review back to SBSTA 66 on the basis of draft text that does not reflect consensus.','The adopted decision sets procedural next steps. It does not adopt the unresolved draft or change which activities can be listed on the platform.'],
       pt:['Artigo 6.8: abordagens não mercadológicas','A CMA decidiu realizar oficinas e convidou Partes e observadores a contribuir. A revisão ainda em aberto segue para o SBSTA 66, com base em um texto sem consenso.','A decisão aprovada define os próximos passos do processo. Não aprova o texto pendente nem altera quais atividades podem ser registradas na plataforma.']},
      {id:'response-measures',topic:'justice',body:'COP 31 · 12 / CMP 21 · 7 / CMA 8 · 15',status:'notAdopted',stage:'draft',source:enb,
       en:['Forum on response measures','The joint draft on the socioeconomic effects of climate policies did not secure consensus. The matter was forwarded to SB 66.','FCCC/CP/2026/L.12, FCCC/KP/CMP/2026/L.5 and FCCC/PA/CMA/2026/L.21 did not become decisions. The disputed proposals on the Forum’s work and inputs to the next global stocktake were not adopted.'],
       pt:['Fórum sobre medidas de resposta','A proposta conjunta sobre os efeitos socioeconômicos das políticas climáticas não obteve consenso. O tema foi encaminhado à SB 66.','FCCC/CP/2026/L.12, FCCC/KP/CMP/2026/L.5 e FCCC/PA/CMA/2026/L.21 não se tornaram decisões. Não foram aprovadas as propostas em disputa sobre o trabalho do Fórum e os insumos ao próximo Balanço Global.']}
    ],
    milestones:[
      {id:'adaptation-fund-cmp',date:'2027-01-01',precision:'byDay',en:'Amendments to the Fund’s governing decision take effect; the transition has a separate trigger.',pt:'Entram em vigor alterações à decisão que rege o Fundo; a transição depende de uma condição distinta.'},
      {id:'adaptation',date:'2027-02-28',precision:'byDay',en:'Deadline for nominations to the adaptation indicators task force.',pt:'Prazo para indicações à força-tarefa sobre indicadores de adaptação.'},
      {id:'article-6-8',date:'2027-03-31',precision:'byDay',en:'Deadline for Parties and observers to suggest topics for the workshop at the Glasgow Committee’s 11th meeting.',pt:'Prazo para Partes e observadores sugerirem temas para a oficina da 11ª reunião do Comitê de Glasgow.'},
      {id:'just-transition',session:'SB 66',en:'Develop the functions and operating arrangements of the just transition mechanism.',pt:'Desenvolver as funções e as regras de funcionamento do mecanismo de transição justa.'},
      {id:'response-measures',session:'SB 66',en:'Continue consideration of response measures after the joint draft failed to secure agreement.',pt:'Continuar a análise das medidas de resposta após a proposta conjunta não obter consenso.'},
      {id:'article-6-2',session:'SB 66',en:'Hold a further informal dialogue on the results of the Article 6 technical expert reviews.',pt:'Realizar novo diálogo informal sobre os resultados das revisões técnicas do Artigo 6.'},
      {id:'article-6-2-funding',session:'SBI 66',en:'Continue discussions using the draft text and a Secretariat paper due before SB 66, with a view to a decision at CMA 9.',pt:'Prosseguir com base na minuta e no documento do Secretariado previsto para antes da SB 66, com vistas a uma decisão na CMA 9.'},
      {id:'article-6-8',session:'SBSTA 66',en:'Consider the unresolved review on the basis of draft text that does not reflect consensus, with a view to recommending a decision to CMA 9.',pt:'Examinar a revisão pendente com base no texto sem consenso, com vistas a recomendar uma decisão à CMA 9.'},
      {id:'adaptation',date:'2027-08-01',precision:'byMonth',en:'Virtual technical dialogue, open to Parties and observers, on lessons from testing the indicators.',pt:'Diálogo técnico virtual, aberto a Partes e observadores, sobre aprendizados dos testes dos indicadores.'},
      {id:'adaptation',date:'2027-08-31',precision:'byDay',en:'Deadline for Parties to submit experience and lessons from testing the indicators.',pt:'Prazo para as Partes enviarem experiências e aprendizados sobre os testes dos indicadores.'},
      {id:'article-6-8',date:'2027-08-31',precision:'byDay',en:'Deadline for Parties and observers to suggest topics for the workshop at the Glasgow Committee’s 12th meeting.',pt:'Prazo para Partes e observadores sugerirem temas para a oficina da 12ª reunião do Comitê de Glasgow.'},
      {id:'loss-and-damage-fund-cma',session:'Before CMA 9',en:'Parties can submit input on further guidance no later than 10 weeks before CMA 9. The Standing Committee on Finance considers submissions for its draft guidance.',pt:'As Partes podem enviar contribuições até 10 semanas antes da CMA 9. O Comitê Permanente de Financiamento deve considerá-las ao elaborar a proposta de novas orientações.'},
      {id:'mitigation',session:'CMA 9',en:'The mitigation item returns for consideration; no extension was agreed at CMA 8.',pt:'O tema volta à pauta. A CMA 8 não aprovou a prorrogação do programa.'},
      {id:'climate-finance',session:'CMA 9',en:'Consider the work programme and its annual report, and provide guidance for the work in 2028.',pt:'Examinar o programa de trabalho e seu relatório anual e orientar as atividades para 2028.'}
    ]
  };
})();
